const fs = require('fs');

fs.readFile('./src/style/light.css', 'utf8', (err, data) => {
  if (err) throw err;
  fs.writeFile(
    './src/style/light.js',
    `const lightTheme = \`${data}\`;
export default lightTheme;
`,
    (err) => { if (err) throw err; }, // eslint-disable-line no-shadow
  );
});

